# flake8: noqa

import collections
import copy
import multiprocessing
import random
import select
import socket
import threading
import time
import traceback
import re

import ta_emss.utilities.xterm_lib.asncoder as asncoder
import ta_emss.utilities.xterm_lib.message_def as message_def
import ta_emss.utilities.xterm_lib.message_rrc_def as message_rrc_def
import ta_emss.utilities.xterm_lib.xsocket as xsocket
from ta_emss.utilities.xterm_lib.timer import Timer
from ta_emss.utilities.xterm_lib.flogger import Flogger
from ta_emss.utilities.xterm_lib.defs import *

g_debug = False
g_enable_prints = True

MAX_PENDING_TASKS = 20


class VDUConn(threading.Thread):
    def __init__(
        self,
        vdu_config,
        local_ip,
        farend_ip=None,
        client=None,
        f1ap_config=None,
        logger=None,
        parent_sch=None,
        log_screen=True,
        log_file=True,
        asn_coder=None,
    ):
        super(VDUConn, self).__init__()
        self.local_ip = local_ip

        self.farend_ip = farend_ip
        self.client = client
        self.socket = None
        self.asn_coder = asn_coder

        self.f1ap_config = f1ap_config if f1ap_config is not None else {}

        self.asn_coder_rrc = asncoder.ASNCoder(protocol="RRC5G")
        self.port = 38472
        self.new_vdu_config = copy.deepcopy(vdu_config)
        self.vdu_config = copy.deepcopy(vdu_config)
        self.running = False
        self.logger = logger
        self.log_screen = log_screen
        self.log_file = log_file
        self.parent_sch = parent_sch
        self.num_msg_rx = 0
        self.num_msg_tx = 0
        self.errors = 0
        self.hb = 0
        self.gnb_id = self.vdu_config["GNB_DU_ID"]
        self.mcc = self.vdu_config["MCC"]
        self.mnc = self.vdu_config["MNC"]
        self.arfcn = self.vdu_config["ARFCN"]
        self.ue_pdcp_nr = {}
        self.transaction_id = 0
        self.link_state = None  # "INIT", "CONNECTED", "CLOSED"
        self.link_substate = (
            None  # "NONE", "SETUP_REQUEST", "CONFIG_UPDATE", "CONFIG_UPDATE_FAILURE"
        )
        self.tasks = collections.deque()
        self.task_map = {
            TSK_F1_SETUP: self.setup_link,
            TSK_GNB_CONFIGURATION_UPDATE: self.send_update,
            TSK_CFG_INC_PCI: self.cfg_inc_pci,
            TSK_CFG_INC_TAC: self.cfg_inc_tac,
            TSK_CFG_INC_GNB_ID: self.cfg_inc_gnb_id,
            TSK_CFG_INC_MCC: self.cfg_inc_mcc,
            TSK_CFG_INC_MNC: self.cfg_inc_mnc,
            TSK_CFG_INC_EARFCN: self.cfg_inc_earfcn,
            TSK_CFG_INC_CELL_ID: self.cfg_inc_cell_id,
        }
        self.timers = {
            TMR_F1_SETUP: Timer(
                self.f1ap_config["SETUP_PERIOD"],
                callback=self.setup_link,
                retries=(
                    self.f1ap_config["SETUP_RETRIES"]
                    if "SETUP_RETRIES" in self.f1ap_config
                    else 3
                ),
            )
            if "SETUP_PERIOD" in self.f1ap_config
            else None,
        }

    def is_timer_running(self, tname):
        ret = False
        if tname in self.timers and self.timers[tname] is not None:
            ret = self.timers[tname].is_running()
        return ret

    def start_timer(self, tname):
        if tname in self.timers and self.timers[tname] is not None:
            self.timers[tname].start()

    def stop_timer(self, tname):
        if tname in self.timers and self.timers[tname] is not None:
            self.timers[tname].stop()

    def check_timers(self):
        ret = True
        for tname in self.timers.keys():
            if (
                self.timers[tname] is not None
                and self.timers[tname].is_running()
                and self.timers[tname].check_expired()
            ):
                if g_debug: self.log("Timer {} expired.".format(tname))
                ret = False
        return ret

    def get_num_pending_tasks(self):
        return len(self.tasks)

    def put_task(self, task):
        num_pending = self.get_num_pending_tasks()
        if g_debug: self.log("Inserting task={} (pending={}).".format(task, num_pending))
        self.tasks.append(task)

    def get_task_params(self, task):
        srch = re.search(r"\[(.*)\]", task)
        if srch:
            params = srch.group(1).split(",")
            return params
        return []

    def process_task(self):
        num_pending = self.get_num_pending_tasks()
        for i in range(num_pending):
            task = self.tasks.popleft()
            if g_debug: self.log("Processing task={} (pending={}).".format(task, num_pending))
            if task in self.task_map:
                self.task_map[task]()
            elif task.find("UE_ADD") != -1:
                task_params = self.get_task_params(task)
                self.ue_setup_request(task_params)
            elif task.find("UE_DEL") != -1:
                task_params = self.get_task_params(task)
                self.ue_deregister_request(task_params)
            elif task.find("UE_BEARER") != -1:
                task_params = self.get_task_params(task)
                self.ue_pdu_session_establishment_request(task_params)
            else:
                self.log("WARNING: process_task: Task not defined: {}".format(task))

    def get_vdu_config(self):
        return {"OLD": self.vdu_config, "NEW": self.new_vdu_config}

    def cfg_inc_pci(self):
        for i, cell in enumerate(self.new_vdu_config["SERVED_CELLS"]):
            pci_max = (
                self.new_vdu_config["PCI_MAX"]
                if "PCI_MAX" in self.new_vdu_config
                else 503
            )
            cell["PCI"] += 3
            if cell["PCI"] >= pci_max + 1:
                cell["PCI"] -= pci_max + 1

    def cfg_inc_cell_id(self):
        for i, cell in enumerate(self.new_vdu_config["SERVED_CELLS"]):
            cell["CELL_ID"] += 1
            if cell["CELL_ID"] >= 256:
                cell["CELL_ID"] -= 256

    def cfg_inc_tac(self):
        self.new_vdu_config["TAC"] += 1
        if self.new_vdu_config["TAC"] > 65535:
            self.new_vdu_config["TAC"] = 1

    def cfg_inc_gnb_id(self):
        self.new_vdu_config["GNB_DU_ID"] += 1000
        if self.new_vdu_config["GNB_DU_ID"] > 1048575:
            self.new_vdu_config["GNB_DU_ID"] = self.gnb_id

    def cfg_inc_mcc(self):
        mcc = int(self.new_vdu_config["MCC"])
        mcc += 1
        if mcc > 999:
            mcc = self.mcc
        self.new_vdu_config["MCC"] = "{:03d}".format(mcc)

    def cfg_inc_mnc(self):
        mnc = int(self.new_vdu_config["MNC"])
        mnc += 10
        if mnc > 999:
            mnc = self.mnc

        if mnc <= 99:
            self.new_vdu_config["MNC"] = "{:02d}".format(mnc)
        else:
            self.new_vdu_config["MNC"] = "{:03d}".format(mnc)

    def cfg_inc_earfcn(self):
        self.new_vdu_config["ARFCN"] += 10
        if self.new_vdu_config["ARFCN"] > 65535:
            self.new_vdu_config["ARFCN"] = self.arfcn

    def open_client_socket(self):
        try:
            if g_debug: self.log("Creating F1AP Client SCTP socket...")
            self.socket = xsocket.get_sctp_socket(self.local_ip)
            if g_debug: self.log("Binding F1AP Client SCTP socket to local ip addr={}.".format(self.local_ip))
            self.socket.bind((self.local_ip, self.port))
            if g_debug: self.log("Connecting F1AP Client to farend ip addr={}.".format(self.farend_ip))
            xsocket.connect(self.socket, self.farend_ip, self.port)
            if g_enable_prints: self.log("F1AP Client connected {}.".format(self.local_ip))
        except socket.error as err:
            self.logerror("Could not open f1ap client socket: {}.".format(err))
            self.socket.close()
            self.socket = None
        except Exception as ex:
            self.logerror("Exception-open_client_socket[{}]".format(ex))
            self.socket = None

    def close_client_socket(self):
        if self.socket:
            self.socket.shutdown(socket.SHUT_RDWR)
            self.socket.close()
        self.socket = None

    def desc(self):
        return "[{}] (hb:{}, rx:{}, tx:{}, err:{}, state:{}, substate:{}, local={}, far={}, tasks={})".format(
            self.gnb_id,
            self.hb,
            self.num_msg_rx,
            self.num_msg_tx,
            self.errors,
            self.link_state,
            self.link_substate,
            self.local_ip,
            self.farend_ip,
            len(self.tasks),
        )

    def send_msg(self, msg_hex, msg_desc):
        if not self.socket:
            self.logerror(
                "Cannot send message {} - no client connected.".format(msg_desc)
            )
            return 0
        try:
            if g_enable_prints: self.log("<--- Sending F1AP {}".format(msg_desc))
            if g_debug: self.logfile("[{}]".format(msg_hex))
            xsocket.send(self.socket, bytes.fromhex(msg_hex))
            self.num_msg_tx += 1
        except Exception as exc:
            self.logerror("Unable to send F1AP {} ({}).".format(msg_desc, exc))
            return 0
        return 1

    def is_link_ready(self):
        return self.link_state == LS_CONNECTED and self.link_substate == LSS_NONE

    def setup_link(self):
        if self.is_link_ready():
            if g_debug: self.log("Link is already established.")
            return

        if self.is_timer_running(TMR_F1_SETUP):
            return

        msg_desc = "F1SetupRequest with PCIs="
        for i, cell in enumerate(self.vdu_config["SERVED_CELLS"]):
            msg_desc += "c{}({})".format(i + 1, cell["PCI"])

        self.set_vdu_config_next_transaction_id()
        msg_str = message_def.F1SetupRequest(self.vdu_config)
        msg_hex = self.asn_coder.encode_asn(msg_str)
        if g_debug: self.logfile("Sending F1SetupRequest={}".format(msg_str))
        self.send_msg(msg_hex, msg_desc)
        self.change_state(lss=LSS_SETUP_REQUEST)
        self.start_timer(TMR_F1_SETUP)

    def send_update(self):
        if not self.is_link_ready():
            return

        if self.is_timer_running(TMR_GNB_CONFIGURATION_UPDATE):
            return

        all_cells = self.f1ap_config["CONFIG_UPDATE_ALL_CELLS"] if "CONFIG_UPDATE_ALL_CELLS" in self.f1ap_config else False
        if all_cells:
            self.send_update_all_cells()
        else:
            self.send_update_one_cell()
        self.start_timer(TMR_GNB_CONFIGURATION_UPDATE)

    def send_update_one_cell(self):
        served_cells = copy.deepcopy(self.vdu_config["SERVED_CELLS"])
        for cell in served_cells:
            self.vdu_config["SERVED_CELLS"] = [cell]
            self.send_configuration_update()
        self.vdu_config["SERVED_CELLS"] = served_cells

    def send_update_all_cells(self):
        if g_debug: self.logfile("Sending vDU config update with all cells")
        self.send_configuration_update()

    def send_configuration_update(self):
        self.set_vdu_config_next_transaction_id()
        msg_str = message_def.F1GNBDUConfigurationUpdate(self.vdu_config)
        if g_debug: self.logfile("Sending GNBDUConfigurationUpdate={}".format(msg_str))
        msg_hex = self.asn_coder.encode_asn(msg_str)
        self.send_msg(msg_hex, "GNBDUConfigurationUpdate")

    def ue_setup_request(self, params):
        [ue_id, du_id, cell_id] = [int(p) for p in params]

        if du_id != self.gnb_id:
            return

        if not self.is_link_ready():
            self.logerror("Cannot add UE-{}, DU-{}, CELL-{}: F1 link not ready".format(ue_id, du_id, cell_id))
            return

        try:
            bts_cell_id = self.vdu_config["SERVED_CELLS"][cell_id - 1]["CELL_ID"]
            if g_debug: self.log("Adding UE ID={} on gNB DU ID={} and CELL={}.".format(ue_id, du_id, bts_cell_id))
            self.vdu_config['UE_ID'] = ue_id
            self.vdu_config['CELL_ID'] = bts_cell_id

            rrc_container = message_rrc_def.rrcSetupRequest(self.vdu_config)
            if g_debug: self.logfile("Sending RRCContainer={}".format(rrc_container))
            rrc_container_hex = self.asn_coder_rrc.encode_rrc5g_asn(rrc_container)
            self.vdu_config['RRCContainer'] = rrc_container_hex
            du_tu_cu_rrc_container = message_rrc_def.CellGroupConfig(self.vdu_config)
            if g_debug: self.logfile("Sending DUtoCURRCContainer={}".format(du_tu_cu_rrc_container))
            du_tu_cu_rrc_container_hex = self.asn_coder_rrc.encode_rrc5g_asn(du_tu_cu_rrc_container)
            self.vdu_config['DUtoCURRCContainer'] = du_tu_cu_rrc_container_hex

            msg_str = message_def.F1InitialULRRCMessageTransfer(self.vdu_config)
            if g_debug: self.logfile("Sending InitialULRRCMessageTransfer={}".format(msg_str))
            msg_hex = self.asn_coder.encode_asn(msg_str)
            self.send_msg(msg_hex, "InitialULRRCMessageTransfer (UE-{})".format(ue_id))
            self.ue_pdcp_nr[ue_id] = 0
        except Exception as exc:
            self.logerror("Cannot add UE-{}, DU-{}, CELL-{}: {}".format(ue_id, du_id, cell_id, exc))

    def ue_deregister_request(self, params):
        [ue_id, du_id, cell_id] = [int(p) for p in params]

        if du_id != self.gnb_id:
            return

        if not self.is_link_ready():
            self.logerror("Cannot delete UE-{}, DU-{}, CELL-{}: F1 link not ready".format(ue_id, du_id, cell_id))
            return

        pdcp_nr = self.get_next_ue_pdcp_nr(ue_id)
        if pdcp_nr is None:
            return

        try:
            bts_cell_id = self.vdu_config["SERVED_CELLS"][cell_id - 1]["CELL_ID"]
            if g_debug: self.log("Deleting UE ID={} on gNB DU ID={} and CELL={}.".format(ue_id, du_id, bts_cell_id))
            self.vdu_config['UE_ID'] = ue_id
            self.vdu_config['CELL_ID'] = bts_cell_id
            self.vdu_config['NAS_PDU_TYPE'] = 'Deregistration-request'
            msg_str = self.ue_ul_information_transfer(pdcp_nr)
            if g_debug: self.logfile("Sending ULRRCMessageTransfer={}".format(msg_str))
            msg_hex = self.asn_coder.encode_asn(msg_str)
            self.send_msg(msg_hex, "ULRRCMessageTransfer (UE-{})".format(ue_id))
            del self.ue_pdcp_nr[ue_id]
        except Exception as exc:
            self.logerror("Cannot delete UE-{}, DU-{}, CELL-{}: {}".format(ue_id, du_id, cell_id, exc))

    def ue_pdu_session_establishment_request(self, params):
        [ue_id, du_id, cell_id] = [int(p) for p in params]

        if du_id != self.gnb_id:
            return

        if not self.is_link_ready():
            self.logerror("Cannot add bearer for UE-{}, DU-{}, CELL-{}: F1 link not ready".format(ue_id, du_id, cell_id))
            return

        pdcp_nr = self.get_next_ue_pdcp_nr(ue_id)
        if pdcp_nr is None:
            return
        try:
            bts_cell_id = self.vdu_config["SERVED_CELLS"][cell_id - 1]["CELL_ID"]
            if g_debug: self.log("Adding bearer for UE ID={} on gNB DU ID={} and CELL={}.".format(ue_id, du_id, bts_cell_id))
            self.vdu_config['UE_ID'] = ue_id
            self.vdu_config['CELL_ID'] = bts_cell_id
            self.vdu_config['NAS_PDU_TYPE'] = 'PDU-session-establishment-request'
            msg_str = self.ue_ul_information_transfer(pdcp_nr)
            if g_debug: self.logfile("Sending ULRRCMessageTransfer={}".format(msg_str))
            msg_hex = self.asn_coder.encode_asn(msg_str)
            self.send_msg(msg_hex, "ULRRCMessageTransfer (UE-{})".format(ue_id))
        except Exception as exc:
            self.logerror("Cannot add bearer for UE-{}, DU-{}, CELL-{}: {}".format(ue_id, du_id, cell_id, exc))

    def ue_setup_complete(self, pdcp_nr):
        rrc_container = message_rrc_def.rrcSetupComplete(self.vdu_config)
        rrc_container_hex = self.asn_coder_rrc.encode_rrc5g_asn(rrc_container)
        self.vdu_config['RRCContainer'] = self.get_pdcp_rrc_container(pdcp_nr, rrc_container_hex)
        msg_str = message_def.F1ULRRCMessageTransfer(self.vdu_config)
        return msg_str

    def ue_ul_information_transfer(self, pdcp_nr):
        rrc_container = message_rrc_def.ulInformationTransfer(self.vdu_config)
        rrc_container_hex = self.asn_coder_rrc.encode_rrc5g_asn(rrc_container)
        self.vdu_config['RRCContainer'] = self.get_pdcp_rrc_container(pdcp_nr, rrc_container_hex)
        msg_str = message_def.F1ULRRCMessageTransfer(self.vdu_config)
        return msg_str

    def process_DLRRCMessageTransfer(self, msg):
        gnb_du_ue_f1ap_id = self.asn_coder.extract_gnb_du_ue_f1ap_id(msg)
        gnb_cu_ue_f1ap_id = self.asn_coder.extract_gnb_cu_ue_f1ap_id(msg)
        ue_id = gnb_du_ue_f1ap_id
        self.vdu_config['UE_ID'] = ue_id
        self.vdu_config['GNB-CU-UE-F1AP-ID'] = gnb_cu_ue_f1ap_id
        self.vdu_config['SRBID'] = 1

        if g_debug: self.log("Received DLRRCMessageTransfer (DU_ID={}, CU_ID={})".format(ue_id, gnb_cu_ue_f1ap_id))

        pdcp_nr = self.get_next_ue_pdcp_nr(ue_id)
        if pdcp_nr is None:
            return

        msg_str = None
        if pdcp_nr == 0:
            msg_str = self.ue_setup_complete(pdcp_nr)
        elif pdcp_nr == 1:
            self.vdu_config['NAS_PDU_TYPE'] = 'Authentication-response'
            msg_str = self.ue_ul_information_transfer(pdcp_nr)
        elif pdcp_nr == 2:
            self.vdu_config['NAS_PDU_TYPE'] = 'Encrypted-data'
            msg_str = self.ue_ul_information_transfer(pdcp_nr)
        elif pdcp_nr == 3:
            self.vdu_config['NAS_PDU_TYPE'] = 'Registration-complete'
            msg_str = self.ue_ul_information_transfer(pdcp_nr)
        else:
            rrc_hex = self.process_DLRRCMessageTransfer_RRCContainer(msg, pdcp_nr)
            if rrc_hex:
                self.vdu_config['RRCContainer'] = rrc_hex
                msg_str = message_def.F1ULRRCMessageTransfer(self.vdu_config)

        if msg_str:
            if g_debug: self.log("[UE-{}] Sending ULRRCMessageTransfer with pdcp_nr={}".format(ue_id, pdcp_nr))
            if g_debug: self.logfile("Sending ULRRCMessageTransfer={}".format(msg_str))
            msg_hex = self.asn_coder.encode_asn(msg_str)
            self.send_msg(msg_hex, "ULRRCMessageTransfer (UE-{})".format(ue_id))

    def process_DLRRCMessageTransfer_RRCContainer(self, msg, pdcp_nr):
        ue_id = self.vdu_config['UE_ID']
        rrc_hex = None
        rrc_msg = None
        try:
            recv_rrc_pdcp_hex = self.asn_coder_rrc.get_rrc_container(msg)
            recv_rrc = self.asn_coder_rrc.get_rrc_from_pdcp(recv_rrc_pdcp_hex)
            recv_pdcp_nr = self.asn_coder_rrc.get_nr_from_pdcp(recv_rrc_pdcp_hex)
            recv_rrc_msg = self.asn_coder_rrc.decode_rrc5g_asn_dl_dcch(recv_rrc)
            if g_debug: self.log("[UE-{}] Received RRC message with pdcp_nr={}".format(ue_id, recv_pdcp_nr))
            if g_debug: self.logfile("Received RRC message={}".format(recv_rrc_msg))
            if recv_rrc_msg.find("securityModeCommand") != -1:
                if g_debug: self.log("[UE-{}] Processing DLRRCMessageTransfer, securityModeCommand".format(ue_id))
                self.vdu_config['rrc-TransactionIdentifier'] = self.asn_coder_rrc.get_rrc_transaction_identifier(recv_rrc_msg)
                rrc_msg = message_rrc_def.securityModeComplete(self.vdu_config)
            elif recv_rrc_msg.find("ueCapabilityEnquiry") != -1:
                if g_debug: self.log("[UE-{}] Processing DLRRCMessageTransfer, ueCapabilityEnquiry".format(ue_id))
                self.vdu_config['rrc-TransactionIdentifier'] = self.asn_coder_rrc.get_rrc_transaction_identifier(recv_rrc_msg)
                rrc_msg = message_rrc_def.ueCapabilityInformation(self.vdu_config)
            elif recv_rrc_msg.find("rrcReconfiguration") != -1:
                if g_debug: self.log("[UE-{}] Processing DLRRCMessageTransfer, rrcReconfiguration".format(ue_id))
                self.vdu_config['rrc-TransactionIdentifier'] = self.asn_coder_rrc.get_rrc_transaction_identifier(recv_rrc_msg)
                rrc_msg = message_rrc_def.rrcReconfigurationComplete(self.vdu_config)
            elif recv_rrc_msg.find("!!! error:") != -1:
                if g_debug: self.log("[UE-{}] Processing DLRRCMessageTransfer (*** encoded ***), recv_pdcp_nr={}".format(ue_id, recv_pdcp_nr))
                if recv_pdcp_nr == 4:
                    rrc_hex = message_rrc_def.ENCODED_RRC['UE-Capability-Information']
        except Exception as exc:
            self.log("[UE-{}] WARNING: Cannot get RRCContainer: {}".format(ue_id, exc))

        if rrc_msg:
            if g_debug: self.logfile("[UE-{}] Sending RRC message: {}".format(ue_id, rrc_msg))
            rrc_container_hex = self.asn_coder_rrc.encode_rrc5g_asn(rrc_msg)
            rrc_hex = self.get_pdcp_rrc_container(pdcp_nr, rrc_container_hex)

        return rrc_hex

    def process_UEContextReleaseCommand(self, msg):
        gnb_du_ue_f1ap_id = self.asn_coder.extract_gnb_du_ue_f1ap_id(msg)
        gnb_cu_ue_f1ap_id = self.asn_coder.extract_gnb_cu_ue_f1ap_id(msg)
        ue_id = gnb_du_ue_f1ap_id
        self.vdu_config['UE_ID'] = ue_id
        self.vdu_config['GNB-CU-UE-F1AP-ID'] = gnb_cu_ue_f1ap_id
        if g_debug: self.log("Received UEContextReleaseCommand (UE-{})".format(ue_id))
        msg_str = message_def.F1UEContextReleaseComplete(self.vdu_config)
        if g_debug: self.logfile("Sending F1UEContextReleaseComplete={}".format(msg_str))
        msg_hex = self.asn_coder.encode_asn(msg_str)
        self.send_msg(msg_hex, "UEContextReleaseComplete (UE-{})".format(ue_id))

    def process_UEContextSetupRequest(self, msg):
        gnb_du_ue_f1ap_id = self.asn_coder.extract_gnb_du_ue_f1ap_id(msg)
        gnb_cu_ue_f1ap_id = self.asn_coder.extract_gnb_cu_ue_f1ap_id(msg)
        ue_id = gnb_du_ue_f1ap_id
        self.vdu_config['UE_ID'] = ue_id
        self.vdu_config['GNB-CU-UE-F1AP-ID'] = gnb_cu_ue_f1ap_id
        if g_debug: self.log("Received UEContextSetupRequest (UE-{})".format(ue_id))
        msg_str = message_def.F1UEContextSetupResponse(self.vdu_config)
        if g_debug: self.logfile("Sending UEContextSetupResponse={}".format(msg_str))
        msg_hex = self.asn_coder.encode_asn(msg_str)
        self.send_msg(msg_hex, "UEContextSetupResponse (UE-{})".format(ue_id))

    def get_next_ue_pdcp_nr(self, ue_id):
        if ue_id in self.ue_pdcp_nr:
            ret = self.ue_pdcp_nr[ue_id]
            self.ue_pdcp_nr[ue_id] += 1
            return ret
        self.log("Cannot get pdcp_nr for UE-{}: No such UE.".format(ue_id))
        return None

    def get_pdcp_rrc_container(self, pdcp_nr, rrc_container_hex):
        return "{0:04X}".format(pdcp_nr) + rrc_container_hex + "00000000"

    def print_vdu_config_diff(self, vdu_config, new_vdu_config):
        msg = "F1_CFG_UPD: "
        if vdu_config["MCC"] != new_vdu_config["MCC"]:
            msg += "mcc({} -> {}) ".format(vdu_config["MCC"], new_vdu_config["MCC"])
        if vdu_config["MNC"] != new_vdu_config["MNC"]:
            msg += "mnc({} -> {}) ".format(vdu_config["MNC"], new_vdu_config["MNC"])
        if vdu_config["GNB_DU_ID"] != new_vdu_config["GNB_DU_ID"]:
            msg += "gnb_id({} -> {}) ".format(
                vdu_config["GNB_DU_ID"], new_vdu_config["GNB_DU_ID"]
            )
        if vdu_config["TAC"] != new_vdu_config["TAC"]:
            msg += "tac({} -> {}) ".format(vdu_config["TAC"], new_vdu_config["TAC"])
        if vdu_config["ARFCN"] != new_vdu_config["ARFCN"]:
            msg += "earfcn({} -> {}) ".format(
                vdu_config["ARFCN"], new_vdu_config["ARFCN"]
            )
        for i, cell in enumerate(vdu_config["SERVED_CELLS"]):
            try:
                new_cell = new_vdu_config["SERVED_CELLS"][i]
            except IndexError:
                msg += "DEL(s{}) ".format(i)
                continue
            if cell["PCI"] != new_cell["PCI"]:
                msg += "s{}-pci({} -> {}) ".format(i, cell["PCI"], new_cell["PCI"])
            if cell["CELL_ID"] != new_cell["CELL_ID"]:
                msg += "s{}-cell_id({} -> {}) ".format(
                    i, cell["CELL_ID"], new_cell["CELL_ID"]
                )
        self.log(msg)

    def change_state(self, ls=None, lss=None):
        prev_ls = self.link_state
        prev_lss = self.link_substate

        if ls is not None:
            self.link_state = ls
        if lss is not None:
            self.link_substate = lss

        if (ls is not None) and (ls != prev_ls):
            self.logfile(
                "=== SCE: LS({} -> {}), LSS({} -> {}).".format(
                    prev_ls, self.link_state, prev_lss, self.link_substate
                )
            )
            self.parent_sch.update_status(req=True)

    def process_msg(self, msg_hex_arg):
        recv_msg = "---> Received F1AP "
        self.num_msg_rx += 1
        msg = self.asn_coder.decode_asn(msg_hex_arg)
        if g_debug: self.logfile("F1AP: Received message={}".format(msg))

        if msg.find("ERROR: decoding failed") != -1:
            self.logerror("ASN decoding failed.")
            self.log(msg)
            self.change_state(ls=LS_INIT, lss=LSS_NONE)

        elif msg.find("F1SetupResponse") != -1:
            if g_enable_prints: self.log(recv_msg + "F1SetupResponse")
            self.change_state(ls=LS_CONNECTED, lss=LSS_NONE)
            self.stop_timer(TMR_F1_SETUP)

        elif msg.find("F1SetupFailure") != -1:
            if g_enable_prints: self.log(recv_msg + "F1SetupFailure")
            self.change_state(ls=LS_CONNECTED, lss=LSS_SETUP_FAILURE)
            self.handle_time_to_wait(msg, TMR_F1_SETUP, self.setup_link)

        elif msg.find("F1SetupRequest") != -1:
            self.log(recv_msg + "F1SetupRequest")
            self.set_vdu_config_transaction_id(msg)
            msg_str = message_def.F1SetupResponse(self.vdu_config)
            if g_debug: self.logfile("Sending F1SetupResponse={}".format(msg_str))
            msg_hex = self.asn_coder.encode_asn(msg_str)
            if self.send_msg(msg_hex, "F1SetupResponse"):
                self.change_state(ls=LS_CONNECTED, lss=LSS_NONE)

        elif msg.find("Reset") != -1:
            self.log(recv_msg + "Reset")
            self.set_vdu_config_transaction_id(msg)
            msg_str = message_def.ResetAcknowledge(self.vdu_config)
            if g_debug: self.logfile("Sending ResetAcknowledge={}".format(msg_str))
            msg_hex = self.asn_coder.encode_asn(msg_str)
            if self.send_msg(msg_hex, "ResetAcknowledge"):
                self.change_state(ls=LS_CONNECTED, lss=LSS_NONE)

        elif msg.find("GNBCUConfigurationUpdate") != -1:
            self.log(recv_msg + "GNBCUConfigurationUpdate")
            self.set_vdu_config_transaction_id(msg)
            msg_str = message_def.F1GNBCUConfigurationUpdateAcknowledge(self.vdu_config)
            if g_debug: self.logfile("Sending GNBCUConfigurationUpdateAcknowledge={}".format(msg_str))
            msg_hex = self.asn_coder.encode_asn(msg_str)
            if self.send_msg(msg_hex, "GNBCUConfigurationUpdateAcknowledge"):
                self.change_state(ls=LS_CONNECTED, lss=LSS_NONE)
            time.sleep(3)
            self.set_vdu_config_service_state(msg)
            self.send_update()
            self.reset_vdu_config_service_state()

        elif msg.find("GNBDUConfigurationUpdateAcknowledge") != -1:
            self.log(recv_msg + "GNBDUConfigurationUpdateAcknowledge")
            self.change_state(ls=LS_CONNECTED, lss=LSS_NONE)
            self.stop_timer(TMR_GNB_CONFIGURATION_UPDATE)

        elif msg.find("GNBDUConfigurationUpdateFailure") != -1:
            self.log(recv_msg + "GNBDUConfigurationUpdateFailure")
            self.change_state(ls=LS_CONNECTED, lss=LSS_NONE)
            self.stop_timer(TMR_GNB_CONFIGURATION_UPDATE)
            self.handle_time_to_wait(msg, TMR_GNB_CONFIGURATION_UPDATE, self.send_update)

        elif msg.find("DLRRCMessageTransfer") != -1:
            self.log(recv_msg + "DLRRCMessageTransfer")
            self.process_DLRRCMessageTransfer(msg)

        elif msg.find("UEContextReleaseCommand") != -1:
            self.log(recv_msg + "UEContextReleaseCommand")
            self.process_UEContextReleaseCommand(msg)

        elif msg.find("UEContextSetupRequest") != -1:
            self.log(recv_msg + "UEContextSetupRequest")
            self.process_UEContextSetupRequest(msg)

        else:
            self.log(recv_msg + "Unknown")
            self.log(msg)

        self.reset_vdu_config_transaction_id()

    def set_vdu_config_service_state(self, msg):
        if msg.find("Cells-to-be-Activated-List") != -1:
            self.vdu_config["service-state"] = "in-service"
        else:
            self.vdu_config["service-state"] = "out-of-service"

    def reset_vdu_config_service_state(self):
        self.vdu_config["service-state"] = "in-service"

    def set_vdu_config_transaction_id(self, msg):
        self.vdu_config["TransactionID"] = self.asn_coder.extract_transaction_id(msg)

    def reset_vdu_config_transaction_id(self):
        self.vdu_config["TransactionID"] = 0

    def set_vdu_config_next_transaction_id(self):
        self.transaction_id += 1
        if self.transaction_id > 255:
            self.transaction_id = 0
        self.vdu_config["TransactionID"] = self.transaction_id

    def handle_time_to_wait(self, msg, timer_name, timer_callback):
        ttw = self.asn_coder.extract_time_to_wait(msg)
        if ttw:
            if timer_name in self.timers:
                self.timers[timer_name].stop()
            new_timer = Timer(ttw, callback=timer_callback)
            self.timers[timer_name] = new_timer
            self.timers[timer_name].start()
            if g_enable_prints: self.log("Started TimeToWait timer {}: {} [s]".format(timer_name, ttw))

    def run(self):
        try:
            self.change_state(ls=LS_INIT, lss=LSS_NONE)

            if self.client is None:
                self.open_client_socket()
            else:
                self.socket = self.client[0]
                self.farend_ip = self.client[1][0]

            self.running = True
            while self.running:
                self.hb += 1
                # self.log(" hb={}, ls={}, lss={}".format(self.hb, self.link_state, self.link_substate))

                if self.errors:
                    self.log("Errors exist. Closing connection...")
                    break

                self.process_task()
                if not self.check_data():
                    break

                self.check_timers()

            self.close_client_socket()
            if g_enable_prints: self.log("F1AP Client disconnected {}...".format(self.local_ip))
            self.change_state(ls=LS_CLOSED, lss=LSS_NONE)
        except Exception as exc:
            self.log(f"Exception: {exc}")
            self.log(traceback.format_exc())
        self.running = False

    def check_data(self):
        if self.socket is None:
            return False

        inputs = [self.socket]
        # select_timeout = 10
        select_timeout = 1
        ret = True
        try:
            inputready, outputready, exceptready = select.select(
                inputs, [], [], select_timeout
            )
            if len(inputready):
                try:
                    data = xsocket.recv(self.socket)
                    if data:
                        self.logfile(
                            "F1AP Client Data received from {}, len={}.".format(
                                self.local_ip, len(data)
                            )
                        )
                        data = data.hex().upper()
                        if g_debug: self.logfile("[{}]".format(data))
                        self.process_msg(msg_hex_arg=data)
                    else:
                        self.logerror("F1AP Farend connection closed.")
                        ret = False
                except socket.timeout:
                    self.logerror("F1AP Client Socket timeout")
                    ret = False
                except socket.error as err:
                    self.logerror("F1AP Client Socket error:{}".format(err))
                    ret = False
        except select.error as err:
            self.logerror("F1AP Client Data select error: {}.".format(err))
            ret = False
        return ret

    def is_running(self):
        return self.running

    def stop(self):
        self.running = False

    def loginf(self):
        return "[" + str(self.gnb_id) + "-" + str(self.farend_ip) + "] "

    def log(self, msg):
        msg_out = self.logfile(msg)
        if self.log_screen:
            print(msg_out)

    def logfile(self, msg):
        msg_out = self.loginf() + str(msg)
        if not self.log_file:
            return msg_out
        if self.logger:
            msg_out = self.logger.write(msg_out)
            self.logger.flush_if_necessary()
        return msg_out

    def logerror(self, msg):
        msg_out = "ERROR: " + msg
        self.log(msg_out)
        self.errors += 1


class SchedulerF1(multiprocessing.Process):
    def __init__(self, id, mdict, gnbs, db, mp_pipe, mp_lock):
        super(SchedulerF1, self).__init__()
        self.id = id
        self.mdict = mdict
        self.db = db
        self.mp_pipe = mp_pipe
        self.mp_lock = mp_lock
        self.gnbs = []
        self.port = 38472
        self.logger = None
        self.log_screen = db.log_screen
        self.log_file = db.log_file
        self.semaphore = threading.BoundedSemaphore()
        self.running = multiprocessing.Event()

        for gnb in gnbs:
            self.gnbs.append(
                {
                    "GNB_CONFIG": gnb,
                    "EPF1S": [],
                    "SERVER": None,
                    "GNB_CONN_VARS": {
                        "num_gnb_resets": 0,
                        "num_gnb_reinits": 0,
                        "gnb_stop_timer": Timer(10),
                    },
                }
            )

        self.connect_on_start = self.db.get("CONNECT_ON_START", default=False)
        self.server_mode = self.db.get("SERVER_MODE", default=True)
        self.f1_setup_delay = self.db.get("F1_SETUP_DELAY", default=0.1)
        self.start_scn = False
        self.scn_durations = {
            "F1_SETUP": [
                random.randint(
                    self.db.get("F1_SETUP_MIN"), self.db.get("F1_SETUP_MAX")
                ),
                self.scn_F1_SETUP,
            ],
            "GNB_CONFIGURATION_UPDATE": [
                random.randint(
                    self.db.get("GNB_CONFIGURATION_UPDATE_MIN"),
                    self.db.get("GNB_CONFIGURATION_UPDATE_MAX"),
                ),
                self.scn_GNB_CONFIGURATION_UPDATE,
            ],
            "LOG_STATUS": [60, self.scn_LOG_STATUS],
        }
        self.timers = {}
        self.cfg_tasks = [
            TSK_CFG_INC_PCI,
            TSK_CFG_INC_TAC,
            # TSK_CFG_INC_GNB_ID,  # Conn reset
            # TSK_CFG_INC_MCC,     # Conn reset
            # TSK_CFG_INC_MNC,     # Conn reset
            TSK_CFG_INC_EARFCN,
            # TSK_CFG_INC_CELL_ID, # Update Failure
        ]
        self.cfg_tasks_idx = 0

    def put_task(self, task_name):
        for gnb in self.gnbs:
            epf1 = self.get_dut_epf1(gnb)
            if epf1 is not None:
                epf1.put_task(task_name)

    def scn_F1_SETUP(self):
        self.put_task(TSK_F1_SETUP)

    def scn_GNB_CONFIGURATION_UPDATE(self):
        if self.cfg_tasks_idx >= len(self.cfg_tasks):
            self.cfg_tasks_idx = 0
        self.put_task(self.cfg_tasks[self.cfg_tasks_idx])
        self.cfg_tasks_idx += 1
        self.put_task(TSK_GNB_CONFIGURATION_UPDATE)

    def scn_LOG_STATUS(self):
        self.log_status()

    def log_status(self):
        for gnb in self.gnbs:
            farend_ip = gnb["GNB_CONFIG"]["FAREND_IP"]
            for epf1 in gnb["EPF1S"]:
                gnb_desc = epf1.desc()
                gnb_num_pending_tasks = epf1.get_num_pending_tasks()
                gnb_is_running = epf1.is_running()
                if farend_ip == epf1.farend_ip:
                    self.logfile(
                        "{}, pending({}), running=({}), reset({}), reinit({}).".format(
                            gnb_desc,
                            gnb_num_pending_tasks,
                            gnb_is_running,
                            gnb["GNB_CONN_VARS"]["num_gnb_resets"],
                            gnb["GNB_CONN_VARS"]["num_gnb_reinits"],
                        )
                    )
                else:
                    self.logfile(
                        "{}, pending({}), running=({}).".format(
                            gnb_desc, gnb_num_pending_tasks, gnb_is_running
                        )
                    )

    # Start already stopped GNB
    def reset_gnb(self, gnb):
        epf1 = self.get_dut_epf1(gnb)
        if epf1 is None:
            return

        # GNB has stopped - is not running
        gnb_id = epf1.gnb_id
        gnb["GNB_CONN_VARS"]["num_gnb_resets"] += 1
        if g_debug: self.log("Joining stopped GNB epf1 ({})...".format(gnb_id))
        epf1.join()
        if g_debug: self.log("Joined ({}).".format(gnb_id))
        self.start_gnb(gnb)

    # Stop and Start running GNB with errors
    def reinit_gnb(self, gnb):
        epf1 = self.get_dut_epf1(gnb)
        if epf1 is None:
            return

        gnb_stop_timer = gnb["GNB_CONN_VARS"]["gnb_stop_timer"]
        # GNB is hung - is running and blocks sending/receiving
        if gnb_stop_timer.is_running():
            if gnb_stop_timer.check_expired():
                gnb["GNB_CONN_VARS"]["num_gnb_reinits"] += 1
                self.log("Reiniting VDU...")
                self.start_gnb(gnb)
        else:
            epf1.stop()
            gnb_stop_timer.start()

    def connect_gnbs(self):
        for gnb in self.gnbs:
            gnb_id = gnb["GNB_CONFIG"]["GNB_DU_ID"]
            epf1 = self.get_dut_epf1(gnb)
            if epf1 is None:
                self.start_gnb(gnb)
                time.sleep(self.f1_setup_delay)
            elif not epf1.is_running():
                self.reset_gnb(gnb)

    def disconnect_gnb(self, gnb_id):
        for gnb in self.gnbs:
            epf1 = self.get_dut_epf1(gnb)
            if epf1 is None:
                continue
            if int(epf1.gnb_id) == int(gnb_id):
                epf1.stop()

    def scenario(self):
        for gnb in self.gnbs:
            epf1 = self.get_dut_epf1(gnb)
            if epf1 is None:
                continue
            gnb_num_pending_tasks = epf1.get_num_pending_tasks()
            if epf1.is_running():
                if gnb_num_pending_tasks >= MAX_PENDING_TASKS:
                    self.reinit_gnb(gnb)
                else:
                    self.check_timers()
            else:
                self.reset_gnb(gnb)

    def start_scenario(self):
        self.log("Starting traffic control scenario.")
        for gnb in self.gnbs:
            epf1 = self.get_dut_epf1(gnb)
            if epf1 is None:
                self.start_gnb(gnb)
        self.start_timers()
        self.start_scn = True

    def stop_scenario(self):
        self.log("Stopping traffic control scenario.")
        self.start_scn = False
        self.stop_timers()

    def init_timers(self):
        for scn_key in self.scn_durations.keys():
            if self.scn_durations[scn_key][0]:
                self.timers[scn_key] = Timer(
                    self.scn_durations[scn_key][0], self.scn_durations[scn_key][1]
                )

    def start_timers(self):
        for scn_key in self.timers.keys():
            self.timers[scn_key].start()

    def stop_timers(self):
        for scn_key in self.timers.keys():
            self.timers[scn_key].stop()

    def check_timers(self):
        for scn_key in self.timers.keys():
            if self.timers[scn_key].check_expired():
                self.timers[scn_key].start()

    def stop(self):
        self.running.clear()

    def is_running(self):
        return self.running.is_set()

    def loginf(self):
        return "[SCHf1-{}] ".format(self.id)

    def logfile(self, msg):
        msg_out = self.loginf() + str(msg)
        if not self.log_file:
            return msg_out
        if self.logger:
            msg_out = self.logger.write(msg_out)
            self.logger.flush_if_necessary()
        else:
            self.logger = Flogger(
                self.db.get_logdir() + "/LOG-EPF1-SCH-" + str(self.id) + ".log"
            )
            self.logger.write("=" * 80)
            self.logger.write("LID=[SCHEDULER]")
            msg_out = self.logger.write(msg_out)
            self.logger.flush_now()
        return msg_out

    def log(self, msg):
        msg_out = self.logfile(msg)
        if self.log_screen:
            print(msg_out)

    def logerror(self, msg):
        msg_out = "ERROR: " + msg
        self.log(msg_out)
        self.mdict["errors"] += 1

    def check_log(self):
        if (
            self.mdict["log_screen"] != self.log_screen
            or self.mdict["log_file"] != self.log_file
        ):
            self.set_log(
                log_screen=self.mdict["log_screen"], log_file=self.mdict["log_file"]
            )

    def set_log(self, log_screen=True, log_file=True):
        if self.log_screen != log_screen:
            self.log_screen = log_screen
            self.set_gnb_log()
        self.log_file = log_file
        self.log("Log to screen={}, log to file={}.".format(log_screen, log_file))

    def set_gnb_log(self):
        for gnb in self.gnbs:
            for epf1 in gnb["EPF1S"]:
                epf1.log_screen = self.log_screen

    def get_dut_epf1(self, gnb):
        farend_ip = gnb["GNB_CONFIG"]["FAREND_IP"]
        for epf1 in gnb["EPF1S"]:
            if farend_ip == epf1.farend_ip:
                return epf1
        return None

    def dut_epf1_exists(self, gnb):
        farend_ip = gnb["GNB_CONFIG"]["FAREND_IP"]
        ret = False
        for epf1 in gnb["EPF1S"]:
            if farend_ip == epf1.farend_ip and epf1.link_state == LS_CONNECTED:
                ret = True
                break
        return ret

    def start_gnb(self, gnb):
        server_stopped = False

        if self.dut_epf1_exists(gnb):
            if g_enable_prints: self.log("VDU already connected: sch_id={}, gnb={}...".format(self.id, gnb["GNB_CONFIG"]["GNB_DU_ID"]))
            return

        if g_enable_prints: self.log("Starting scheduler id={} for gnb={}...".format(self.id, gnb["GNB_CONFIG"]["GNB_DU_ID"]))

        if gnb["SERVER"] is not None:
            if g_enable_prints: self.log("F1 Server is running. Stopping before connecting ({})...".format(gnb["GNB_CONFIG"]["GNB_DU_ID"]))
            # gnb["SERVER"].shutdown(socket.SHUT_RD) #-> [Errno 95] Operation not supported
            gnb["SERVER"].close()
            server_stopped = True

        epf1 = VDUConn(
            gnb["GNB_CONFIG"],
            gnb["GNB_CONFIG"]["IP_ADDR"],
            farend_ip=gnb["GNB_CONFIG"]["FAREND_IP"],
            f1ap_config=self.db.get("F1AP"),
            logger=self.logger,
            parent_sch=self,
            log_screen=self.log_screen,
            log_file=self.log_file,
            asn_coder=asncoder.ASNCoder(protocol="F1AP"),
        )
        epf1.start()
        cnt = 0
        while cnt < 300:
            if epf1.is_running():
                epf1.put_task(TSK_F1_SETUP)
                if g_enable_prints: self.log("VDU started ({}): {}.".format(cnt, epf1.desc()))
                break
            if epf1.link_state == LS_CLOSED:
                if g_enable_prints: self.log("VDU connection closed ({}): {}.".format(cnt, epf1.desc()))
                break
            time.sleep(0.1)
            cnt += 1

        gnb["EPF1S"].append(epf1)

        if server_stopped:
            self.open_server_socket(gnb)

    def update_status(self, req=False):
        if req:
            stime = time.time()
#           if g_debug: self.log("Acquiring STAT mp_lock...")
            self.mp_lock.acquire()
        status = ""
        stat_ls_init = 0
        stat_ls_connected = 0
        stat_ls_closed = 0
        for i, gnb in enumerate(self.gnbs):
            for epf1 in gnb["EPF1S"]:
                status += "  GNB({}):{}\n".format(i, epf1.desc())
                if epf1.link_state == LS_INIT:
                    stat_ls_init += 1
                elif epf1.link_state == LS_CONNECTED:
                    stat_ls_connected += 1
                elif epf1.link_state == LS_CLOSED:
                    stat_ls_closed += 1
        if not req:
            self.semaphore.acquire()
        self.mdict["status"] = status
        self.mdict["stat_ls_init"] = stat_ls_init
        self.mdict["stat_ls_connected"] = stat_ls_connected
        self.mdict["stat_ls_closed"] = stat_ls_closed
        if not req:
            self.semaphore.release()

        if req:
            self.mp_pipe.send("STAT")
            if self.mp_pipe.poll(5):
                ack = self.mp_pipe.recv_bytes()
            self.mp_lock.release()

    def open_server_sockets(self):
        for gnb in self.gnbs:
            self.open_server_socket(gnb)

    def open_server_socket(self, gnb):
        gnb["SERVER"] = None
        ip_addr = gnb["GNB_CONFIG"]["IP_ADDR"]
        gnb_id = gnb["GNB_CONFIG"]["GNB_DU_ID"]
        try:
            sctp_sckt = socket.getprotobyname("sctp")
            if g_debug: self.log("Creating EPF1 Server SCTP socket ({})...".format(gnb_id))
            server = socket.socket(xsocket.get_socket_type(ip_addr), socket.SOCK_STREAM, sctp_sckt)
            server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            if g_debug: self.log("Binding EPF1 Server SCTP socket to local ip addr={} ({}).".format(ip_addr, gnb_id))
            server.bind((ip_addr, self.port))
            if g_enable_prints: self.log("EPF1 Server listening on local ip addr={} ({}).".format(ip_addr, gnb_id))
            server.listen(5)
            server.settimeout(0.1)
            gnb["SERVER"] = server
        except socket.error as err:
            self.logerror(
                "Could not open epf1 server socket for ip={} ({}): {}.".format(
                    ip_addr, gnb_id, err
                )
            )
            if gnb["SERVER"]:
                gnb["SERVER"].close()
                gnb["SERVER"] = None
        except Exception as exc:
            self.logerror(
                "Exception-open_server_socket for ip={} ({}) [{}]".format(
                    ip_addr, gnb_id, exc
                )
            )

    def check_server(self):
        inputs = []

        for gnb in self.gnbs:
            if gnb["SERVER"]:
                inputs.append(gnb["SERVER"])
            elif self.server_mode:
                self.open_server_socket(gnb)

            gnb_id = gnb["GNB_CONFIG"]["GNB_DU_ID"]
            for epf1 in gnb["EPF1S"][:]:
                if epf1.link_state == LS_CLOSED:
                    if g_debug: self.log("Joining closed epf1 for gnb={} ({})...".format(gnb_id, epf1.desc()))
                    epf1.join()
                    if g_debug: self.log("Joined epf1 for gnb={} ({})...".format(gnb_id, epf1.desc()))
                    gnb["EPF1S"].remove(epf1)

        self.update_status()

        if len(inputs) == 0:
            time.sleep(1)
            return True

        # select_timeout = 10 if self.start_scn else 30
        select_timeout = 1
        ret = True
        try:
            inputready, outputready, exceptready = select.select(
                inputs, [], [], select_timeout
            )
            if len(inputready):
                for inp in inputready:
                    for gnb in self.gnbs:
                        if inp == gnb["SERVER"]:
                            try:
                                conn, addr = inp.accept()
                                self.log(
                                    "EPF1 Server: New connection to {}-{} from {}.".format(
                                        gnb["GNB_CONFIG"]["GNB_DU_ID"],
                                        gnb["GNB_CONFIG"]["IP_ADDR"],
                                        addr,
                                    )
                                )
                                eclient = VDUConn(
                                    gnb["GNB_CONFIG"],
                                    gnb["GNB_CONFIG"]["IP_ADDR"],
                                    client=(conn, addr),
                                    logger=self.logger,
                                    parent_sch=self,
                                    log_screen=self.log_screen,
                                    log_file=self.log_file,
                                    asn_coder=asncoder.ASNCoder(protocol="F1AP"),
                                )
                                eclient.start()
                                gnb["EPF1S"].append(eclient)

                            except socket.timeout:
                                self.logerror(
                                    "EPF1 Server: Socket timeout, ip={}".format(
                                        gnb["GNB_CONFIG"]["IP_ADDR"]
                                    )
                                )
                            except socket.error as err:
                                self.logerror(
                                    "EPF1 Server: Socket error, ip={}: {}".format(
                                        gnb["GNB_CONFIG"]["IP_ADDR"], err
                                    )
                                )
                                ret = False
                            except Exception as exc:
                                self.logerror(
                                    "EPF1 Server: Exception for incoming ip={}: {}.".format(
                                        gnb["GNB_CONFIG"]["IP_ADDR"], exc
                                    )
                                )
                                ret = False

        except select.error as exc:
            self.logerror("EPF1 Server: Select error: {}.".format(exc))
            ret = False
        except Exception as exc:
            self.logerror("EPF1 Server: Select Exception: {}.".format(exc))
            ret = False
        return ret

    def run(self):
        self.init_timers()
        if self.connect_on_start:
            for gnb in self.gnbs:
                self.start_gnb(gnb)
        if self.server_mode:
            self.open_server_sockets()
        self.logfile("Durations={}.".format(self.scn_durations))

        self.running.set()
        try:
            while self.running.is_set():
                self.mdict["hb"] += 1
                self.check_server()
                self.update_status()
                self.check_log()

                if self.mdict["req_stop_scn"]:
                    self.log("Stopping scenario [hb={}]".format(self.mdict["hb"]))
                    self.mdict["req_connect"] = False
                    self.mdict["req_start_scn"] = False
                    self.stop_scenario()
                    self.mdict["req_stop_scn"] = False

                if self.mdict["req_start_scn"]:
                    self.log("Starting scenario [hb={}]".format(self.mdict["hb"]))
                    self.mdict["req_connect"] = False
                    self.start_scenario()
                    self.mdict["req_start_scn"] = False

                if self.start_scn:
                    if g_debug: self.log("Processing scenario [hb={}]".format(self.mdict["hb"]))
                    self.scenario()

                if self.mdict["req_connect"]:
                    self.connect_gnbs()

                if self.mdict["req_disconnect"] is not None:
                    self.log("Disconnecting [hb={}]".format(self.mdict["hb"]))
                    self.disconnect_gnb(self.mdict["req_disconnect"])
                    self.mdict["req_disconnect"] = None

                if self.mdict["req_task"]:
                    self.log("Requesting task [hb={}]".format(self.mdict["hb"]))
                    task_list = self.mdict["req_task"].split("|")
                    for i, task_name in enumerate(task_list):
                        if i == len(task_list) - 1:
                            break
                        self.log("Putting task={}.".format(task_name))
                        self.put_task(task_name)
                    self.mdict["req_task"] = ""
        except Exception as exc:
            self.log(f"Exception: {exc}")
            self.log(traceback.format_exc())

        self.log("Stopping scheduler...")
        for gnb in self.gnbs:
            if gnb["SERVER"]:
                gnb["SERVER"].close()
        for gnb in self.gnbs:
            for epf1 in gnb["EPF1S"]:
                epf1.stop()
                if g_debug: self.log("Joining epf1 connection ({}-{})...".format(epf1.gnb_id, epf1.farend_ip))
                epf1.join()
                if g_debug: self.log("Joined epf1 conn ({}-{}).".format(epf1.gnb_id, epf1.farend_ip))
        self.log("SchedulerF1 stopped.")
        self.running.clear()
